INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(149700, 0, 1497, 0, 0, 0, 'Undercity', 'Beneath the broken capital of Lordaeron lies the Undercity, seat of the Forsaken. The old kingdom kept its royal crypts, catacombs, dungeons and sewers here, under the palace of its kings, and the poorest of its people lived in the gloom below. The Scourge began carving these depths into a stronghold, but Arthas left the work unfinished when he was called north. When Sylvanas Windrunner broke free and turned on the dreadlords who ruled the ruins, her Forsaken claimed the warren and finished it as their own. Lifts descend from the ruined palace to the Trade Quarter at its heart, ringed by the Magic Quarter, the Rogues'' Quarter, the War Quarter and the Apothecarium, with foul canals running between them and the Royal Quarter beyond. The city has only lately been won back. After the treachery at the Wrathgate, Varimathras and Grand Apothecary Putress seized it in a bloody coup, and Thrall and Sylvanas retook it by force. Now Kor''kron orcs walk its halls, sent to guard the Forsaken and to watch them.', 'warcraft.wiki.gg/wiki/Undercity (origins as royal crypts, catacombs, dungeons and sewers; poorest citizens lived there; Arthas left it unfinished; Forsaken completed it; quarter layout; elevators exit at Trade Quarter); warcraft.wiki.gg/wiki/Battle_for_the_Undercity (coup, retaking, Kor''kron under Bragor); quest 13257 reward text; npc_text 14931 and 15321 (Kor''kron Overseer gossip); creature 31419 (Sylvanas in Grommash Hold during the crisis phase)'),
(149701, 1, 1497, 1, 0, 0, 'The Elevators', 'Three great lifts join the ruined palace of Lordaeron to the Trade Quarter far below, the main road between the open ruins and the city of the dead. Travelers ride them down long, dark shafts, and their doors close so quickly that the careless learn to step lively. The lifts were a prize in the Battle for the Undercity. The rebels wrecked the way down and trapped the shaft, and Sylvanas warned that a fall would mean certain death. Thrall answered by calling on the spirits of air, and cyclones lowered the Horde''s champions safely into the inner sanctum below.', 'AreaTable 4617 Elevator (parent 1497); WMOAreaTable rows 28864, 28882, 28865 map three Undercity WMO groups to area 4617; warcraft.wiki.gg/wiki/Undercity (elevators connect the upper city to the depths; Trade Quarter at their lower exits; doors close dangerously fast); creature_text 32518 groups 15-17 (elevator destroyed, cyclones lower us to safety); creature_text 32365 group 1 (shaft is trapped)'),
(149702, 2, 1497, 1, 2, 0, 'Lady Sylvanas Windrunner', 'Once Ranger-General of Silvermoon, Sylvanas Windrunner fell defending Quel''Thalas from Arthas and was raised as a banshee in his service. When the Lich King''s grip faltered she broke free, turned on the dreadlords who held Lordaeron and named her freed undead the Forsaken. She rules them from the Royal Quarter, curt with visitors, for the city does not run itself. She championed the blood elves'' entry into the Horde, and sends her chosen to Nathanos Blightcaller, one of her first champions. Betrayed by Varimathras and Putress after the Wrathgate, she barely escaped with her life, then returned beside Thrall to take back her throne.', 'warcraft.wiki.gg/wiki/Sylvanas_Windrunner (Ranger-General, raised by Arthas, broke free, dreadlords, blood elves, Battle for the Undercity); npc_text 10212 (Sylvanas gossip); quest 5961 description (Nathanos among the first of my champions); quests 9621 and 9812 reward text; quest 13257 reward text (Sylvanas nearly killed in the coup)'),
(149703, 2, 1497, 2, 2, 0, 'Varimathras', 'Varimathras was one of three dreadlord brothers who ruled Lordaeron''s undead for the Burning Legion after Arthas went north. When Sylvanas broke his forces he begged for his life and offered his service, and for years he stood at her side in the Royal Quarter as her lieutenant, with the Deathstalkers first serving as his elite guard. His loyalty was a mask. After the Wrathgate he and Putress seized the Undercity and loosed demons and blight on its defenders. Cornered in the throne room by Thrall and Sylvanas, he raged over years of wasted planning and begged pardon of an unseen Master before the Dark Lady struck him down.', 'warcraft.wiki.gg/wiki/Varimathras (brothers Balnazzar and Detheroc, begged Sylvanas for his life, lieutenant, coup, unseen Master); warcraft.wiki.gg/wiki/Deathstalker (began as Varimathras''s elite guard); creature_text 31565 (Varimathras battle lines: years wasted, a thousand-thousand pardons, Master); quest 13266 reward text (demons and blight); quest 13267 description; zone_undercity.cpp: Varimathras entry 31565 summoned in the Horde battle; warcraft.wiki.gg/wiki/Varimathras (defeated by Sylvanas herself; unseen Master rebukes him); zone_undercity.cpp: Varimathras made attackable after SAY_VALIMATHRAS_ATTACK, killable by players for credit'),
(149704, 2, 1497, 3, 0, 0, 'Grand Apothecary Putress', 'Grand Apothecary Putress rose to lead the Royal Apothecary Society after winning Sylvanas''s favor with a vow to take the plague that made the Forsaken and make it their own weapon. From the Apothecarium his chemists refined the New Plague, a blight lethal to living and undead alike, and the Horde even credited him with finding a cure for a recent outbreak of the Scourge''s own plague. At the Wrathgate he turned his blight on Alliance, Horde and Scourge together, striking down Highlord Bolvar Fordragon and many soldiers. With Varimathras he then seized the Undercity. When King Varian''s forces broke into his laboratory, Putress tried to swallow ever more power, raving that he saw everything, and died there.', 'warcraft.wiki.gg/wiki/Royal_Apothecary_Society (Putress founder, New Plague lethal to living and undead, Wrathgate, killed by Varian''s forces); warcraft.wiki.gg/wiki/Battle_for_the_Undercity (Bolvar and thousands of soldiers killed); quest 13257 reward text (Putress discovered the cure for the recent Scourge plague outbreak); creature_text 31530 groups 5-6 (I will consume more energy, I see everything); zone_undercity.cpp: Putress 31530 summoned and fought in the Alliance battle; zone_undercity.cpp (Putress spawned at the Apothecarium position, blight generators empower him; world state APOTHECARIUM_FIGHT_A)'),
(149705, 2, 1497, 4, 2, 0, 'Master Apothecary Faranell', 'Master Apothecary Faranell leads the Royal Apothecary Society from the Apothecarium, overseeing its most ambitious and most ghoulish work: guano from the bats of Razorfen Kraul, hearts cut from Scarlet zealots, venoms and composites sent home by his apothecaries in the field. He speaks of it all with unsettling delight. Since Putress''s betrayal the Society labors under the eye of the Warchief''s Kor''kron, and Faranell has turned diplomat, assuring his overseer that the apothecaries wish only to make amends for a tragic misguidance and to continue their research in peace. Putress, he insists, was an unfortunate anomaly.', 'quests 1109 and 1113 (guano, hearts of Scarlet zealots); quests 513, 515 and 2938 reward text; npc_text 14940 (Faranell gossip: Putress an unfortunate anomaly); creature_text 2055 (make up for the tragic misguidance, continue our research in peace); warcraft.wiki.gg/wiki/Royal_Apothecary_Society (Faranell leads the Society)'),
(149706, 2, 1497, 5, 2, 0, 'Bragor Bloodfist', 'Bragor Bloodfist is a Kor''kron captain sent by Thrall to stand at the Dark Lady''s side after the city was retaken. With most of the Forsaken army committed to Vengeance Landing in Northrend, the Warchief''s guard now reinforces the Undercity, and Bragor has taken up many duties once held by Varimathras: sending agents against the Scarlet Crusade, receiving word from the Hillsbrad front, and hunting a Scourge emissary named Malcin near Razorfen Downs. A living orc among the dead, he keeps dangerous books from the Forsaken as carefully as from the Shadow Council. He judges newcomers by their deeds, and already counts the human king among the threats the Horde must one day end.', 'warcraft.wiki.gg/wiki/Bragor_Bloodfist (Kor''kron captain, replaced Varimathras in 3.3.0, sent by Thrall); npc_text 15321 (forces deployed to Vengeance Landing); quests 6144, 14351, 14352, 14353, 14355, 14356; npc_text 15319 (Bragor gossip on Varimathras); quest 14351 reward text (with that king leading them, the humans remain a problem); quest 14356 (books kept from the Searing Blade and the Forsaken alike)'),
(149707, 2, 1497, 6, 2, 0, 'Overseer Kraggosh', 'Overseer Kraggosh is the Kor''kron orc posted inside the Apothecarium itself, and he makes no secret of how little he likes it. Since Putress loosed his blight at the Wrathgate, the Warchief has trusted the Royal Apothecary Society about as far as he could throw it, and Kraggosh is the result: no abomination guards, no secrecy, no plotting in the dark. The apothecaries can do nothing without him, and he has warned Master Apothecary Faranell that if the Society so much as spits without leave, the place will be shut down by force. His fellow overseers stand watch across the city and treat the Forsaken with open contempt.', 'npc_text 14934 (Kraggosh gossip); creature_text 36217 (I''ve got my eye on you, Faranell; no abominations, no secrecy; spit without my permission); npc_text 14931 and 14933 (Kor''kron Overseer gossip: the forsaken need watching, bonebag); warcraft.wiki.gg/wiki/Royal_Apothecary_Society (Kraggosh warns the apothecaries)'),
(149708, 2, 1497, 7, 2, 0, 'Sharlindra', 'Sharlindra is a banshee of the Dark Lady''s court and long in her service. She was present when Varimathras offered Sylvanas a place in his new order, and privately wondered whether accepting might have been the wiser course. She fought beside the Forsaken when they stormed the stronghold of the dreadlord Detheroc. Today she keeps to the Royal Quarter and directs agents abroad through lieutenants such as Melisara at Tarren Mill. When the ogre Mug''Thol stole the Crown of Will meant for Sylvanas, and the Dark Lady wanted an example made, it was Sharlindra who set the task in motion.', 'warcraft.wiki.gg/wiki/Sharlindra (banshee, Royal Quarter, witnessed Varimathras''s offer, attack on Detheroc''s stronghold, lieutenant Melisara); quests 495 and 521'),
(149709, 2, 1497, 8, 2, 0, 'Parqual Fintallas', 'Before the plague took him, Parqual Fintallas was a great historian of Lordaeron''s human kingdom. Death has not cured him of scholarship. He lingers in the Undercity still seeking enlightenment, though of a different kind, and holds that knowledge of the world will outlast mere strength. To those who would prove their minds he sets a final test of lore, sending them first to the Scarlet Monastery for a book its zealots once used to train paladins against his kind. His question, fittingly, concerns the very creature that became the Lich King and spread the plague across Lordaeron.', 'quest 1159 description (great historian for the humans before the Plague); quest 1160 description (Beginnings of the Undead Threat, used to train paladins against my kind; knowledge more important than strength); npc_text 5822 (his question); quest 6628'),
(149710, 2, 1497, 9, 2, 0, 'Apothecary Zinge', 'Apothecary Zinge of the Royal Apothecary Society has a sharp eye for opportunity, especially other people''s. By her account Apothecary Keever, at work in the next room, is touched in the head, yet his research might bear fruit if pursued by a clever researcher, and Zinge means to be that researcher. She sends her errand runners to Alessandro Luca of Blue Moon Odds and Ends, who pines for her company, and on to the Tanaris desert to test the flesh of basilisks, scorpids and hyenas. She rewards those who stay useful, and corresponds with colleagues as far afield as the Crossroads and Kargath.', 'quests 232 and 238 (Keever is touched, Luca''s kit and his longing for Zinge''s presence); quest 243 (Tanaris samples); quest 864 reward text (Keever''s insanity my genius; reward those who remain useful); quests 1358 (Helbrim at the Crossroads) and 4133 (Vivian Lagrave at Kargath)'),
(149711, 3, 1497, 1, 0, 0, 'The Battle for the Undercity', 'The blight that fell on the Wrathgate was not the end of the treachery. Grand Apothecary Putress and the dreadlord Varimathras had turned much of the Forsaken against their queen, and they seized the Undercity. Sylvanas barely escaped to Orgrimmar, those who would not side with the rebels were executed or banished, and Orgrimmar, now under martial law, took in the Forsaken refugees. Thrall vowed justice. Through portals from Grommash Hold the Horde gathered at the ruins with Vol''jin, then fought down past a wrecked lift and a trapped shaft into the Royal Quarter, where Varimathras fell. Meanwhile King Varian Wrynn, Jaina Proudmoore, Broll Bearmantle and Valeera Sanguinar led the Alliance through the sewers, hunting Putress to his death in the Apothecarium. Then Varian marched on the throne room and turned his blades on Thrall. Only Jaina''s magic, freezing the combatants and carrying the Alliance away, prevented a slaughter. The old fellowship of the Wrathgate did not survive the day.', 'quest 13257 reward text (executed or banished, refugees, martial law); quest 13266 description and reward text; quest 13267 description and reward text (gone are the days of Alliance and Horde battling alongside each other); quests 13371 and 13377 descriptions; creature_text 32518, 32365, 32401, 32402; warcraft.wiki.gg/wiki/Battle_for_the_Undercity (Varian, Jaina, Broll, Valeera in the sewers; Jaina froze the combatants and teleported the Alliance out); creature 31419 (Sylvanas spawned in Grommash Hold during the crisis); zone_undercity.cpp (Horde: courtyard, elevator destroyed, cyclones, Royal Quarter; Alliance: sewers, Putress at the Apothecarium, throne room, Deep Freeze and Greater Mass Teleport)'),
(149712, 3, 1497, 2, 2, 0, 'The Lady''s Necklace', 'In the Ghostlands, a necklace was recovered from the Scourge near Windrunner Spire, bright against the gloom and inscribed as the property of Lady Sylvanas Windrunner. High Executor Mavren at Tranquillien saw that it was a gift to her from her sister Alleria, and sent it on to the Royal Quarter. Sylvanas seized it, startled into memory, then mastered herself and scorned the gift. Alleria, she declared, was a long dead memory, and the trinket meant nothing to the queen of the Forsaken. She let it fall to the floor and dismissed the bearer. Yet a moment later she knelt and took it up again. Whispering ''Belore'', she wove a glamour that called forth the spirits of the Highborne, and the throne room filled with their ancient song of the sin''dorei.', 'quest 9175 description and reward text (Windrunner Spire, inscription, Mavren at Tranquillien); quest 9180 description, completion and reward text; creature_text 10181 groups 0-2 (kneels, Belore, Highborne spirits sing about the Sin''dorei); warcraft.wiki.gg/wiki/Sylvanas_Windrunner (Alleria''s necklace, lament)'),
(149713, 3, 1497, 3, 2, 0, 'The Crown of Will', 'Lady Sylvanas desired the Crown of Will, a relic to be had in Alterac, and sent the ogre Mug''Thol and his Crushridge warband to fetch it, bound to her service by possession. Mug''Thol found the crown and, being an ogre, could not resist putting it on. Its power let him throw off the Dark Lady''s will, and his Crushridge overran the ruins of Alterac. The Dark Lady wanted an example made, and Sharlindra of the Royal Quarter passed the task to her lieutenant Melisara at Tarren Mill. Melisara had the Crushridge thinned, then claimed the heads of Mug''Thol''s lieutenants Targ, Muckrake and Glommus, and at last Mug''Thol''s own, meaning to mount all four on pikes above Alterac. The crown itself returned to Sharlindra, to be laid before the queen it was always meant for.', 'quests 495, 518, 519, 520 and 521 (descriptions and reward text)'),
(149714, 3, 1497, 4, 2, 0, 'The Deathstalkers', 'Promising rogues of the Horde may be summoned to the Rogues'' Quarter by Mennet Carkad, who tests candidates for the Deathstalkers, the Dark Lady''s elite agents. The test is a quiet one. Their leaders suspect Andron Gant, a merchant whose shop stands by the Apothecarium, of selling secrets to some other power. First the candidate must obtain, by whatever means suits, the letter of introduction carried by Astor Hadren, a courier between Silverpine and the Undercity. Posing as the expected messenger, the recruit calls on Andron, who suspects nothing and hands over his ledger with his regards. The ledger names his true buyers: the Syndicate, proof of how far the lords of Alterac have fallen since their betrayal. Carkad welcomes the recruit into the Deathstalkers and sends the new agent to carry the findings to Aleric Hawkins, their master in the Royal Quarter.', 'quests 1885, 14420, 14419, 14421 and 14418 (descriptions, log text and reward text); warcraft.wiki.gg/wiki/Deathstalker (elite assassins and spies; spying on Andron Gant); creature 36517 Aleric Hawkins (The Deathstalkers) spawned beside Sylvanas'),
(149715, 3, 1497, 5, 2, 0, 'Seeping Corruption', 'In the Apothecarium, Chemist Cuely keeps a patient who did not come to be studied. Thersa Windsong, a tauren, was wounded by naga in the Ruins of Eldarath in Azshara and afterward drank from a tide pool on the beach. She has been sick ever since, and no priest or shaman could help her. Cuely, more accommodating than she finds comfortable, has a helper fill labeled vials at the pools so he can learn what she drank. From the samples he brews an elixir and has it carried to her. With nowhere else to turn, Thersa drinks and prays that the Earthmother will watch over her spirit. The elixir takes hold faster than even Cuely dreamed, and she does not survive it. Pleased, the chemist turns at once to the remaining samples, certain they will soon be of use to Lady Sylvanas.', 'quests 3568, 3569 and 3570 (descriptions and reward text); creature_text 8393 and 8390; warcraft.wiki.gg/wiki/Thersa_Windsong (tauren; turns green and dies after drinking the elixir)'),
(149716, 3, 1497, 6, 2, 0, 'The Jeremiah Blues', 'Among the records the Forsaken keep, few are stranger than the city census. Royal Overseer Bauhaus tends it by arcane means and disciplined mind, tracking the populace since the city was freed from the Scourge. When a dusty parcel turned up in the Plaguelands, addressed more than four years earlier to one Jeremiah Felstone of Lordaeron, the census held the answer. Like some Forsaken, Felstone had shed his old name with his old life, and now sold cockroaches as Jeremiah Payson beneath a walkway near the bank. He took the visit badly, since the sender was his sister Janice, dead these four years, until he saw the parcel truly came from her. Inside lay the deed to the Felstone farm, which he declined to reclaim, and half of a good luck charm, which he asked be returned to her restless spirit.', 'quest 5023 description and reward text; quest 5049 description, log text and reward text; quest 5050 description; npc_text 3653 (Bauhaus census gossip)');
